import sys
from collections import deque
from math import gcd as math_gcd

INPUT = sys.stdin
OUTPUT = sys.stdout

reader = INPUT
_tokenizer = []

def readLine():
    return reader.readline()

def readLn():
    return reader.readline().rstrip('\n')

def read():
    global _tokenizer
    while not _tokenizer:
        line = reader.readline()
        if not line:
            return ""
        _tokenizer = line.strip().split()
    return _tokenizer.pop(0)

def readInt():
    return int(read())

def readDouble():
    return float(read())

def readLong():
    return int(read())

def readStrings(n):
    return [read() for _ in range(n)]

def readString():
    return readStrings(1)[0]

def readLines(n):
    return [readLn() for _ in range(n)]

def readInts(n=2):
    return [int(read()) for _ in range(n)]

def readIntArray(n):
    return [int(read()) for _ in range(n)]

def readDoubles(n):
    return [float(read()) for _ in range(n)]

def readDoubleArray(n):
    return [float(read()) for _ in range(n)]

def readLongs(n=2):
    return [int(read()) for _ in range(n)]

def readLongArray(n):
    return [int(read()) for _ in range(n)]

writer = sys.stdout

class UnionFind:
    def __init__(self):
        self.parents = {}
        self.sizes = {}

    def union(self, a, b):
        fa = self.find(a)
        fb = self.find(b)
        if fa != fb:
            self.parents[fa] = fb
            self.sizes[fb] = (self.sizes.get(fb, 1) + self.sizes.get(fa, 1))

    def find(self, a):
        def getOrDefault(value):
            return self.parents.get(value, value)

        parent = getOrDefault(a)
        while parent != getOrDefault(parent):
            self.parents[parent] = getOrDefault(getOrDefault(parent))
            parent = self.parents[parent]
        return parent

    def connected(self, a, b):
        return self.find(a) == self.find(b)

    def getSize(self, a):
        return self.sizes.get(self.find(a), 1)

class UnionFindArray:
    def __init__(self, n):
        self.n = n
        self.parents = list(range(n + 1))

    def union(self, a, b):
        fa = self.find(a)
        fb = self.find(b)
        if fa != fb:
            self.parents[fa] = fb

    def find(self, a):
        parent = self.parents[a]
        while parent != self.parents[parent]:
            self.parents[parent] = self.parents[self.parents[parent]]
            parent = self.parents[parent]
        return parent

    def connected(self, a, b):
        return self.find(a) == self.find(b)

class Trie:
    class Node:
        def __init__(self, hasWord=False):
            self.hasWord = hasWord
            self.children = {}

    def __init__(self):
        self.root = Trie.Node()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = Trie.Node()
            node = node.children[char]
        node.hasWord = True

    def search(self, word):
        node = self.findNode(word)
        return node.hasWord if node is not None else False

    def startsWith(self, prefix):
        return self.findNode(prefix) is not None

    def findNode(self, prefix):
        node = self.root
        for char in prefix:
            node = node.children.get(char)
            if node is None:
                return None
        return node

class BinaryIndexedTree:
    def __init__(self, arg):
        if isinstance(arg, int):
            self.bit = [0] * (arg + 1)
        else:
            nums = arg
            self.bit = [0] * (len(nums) + 1)
            prefix = [0] * len(self.bit)
            for i in range(1, len(nums) + 1):
                prefix[i] = prefix[i - 1] + nums[i - 1]
                self.bit[i] = prefix[i] - prefix[i - self.lowbit(i)]

    def query(self, index):
        result = 0
        i = index + 1
        while i > 0:
            result += self.bit[i]
            i -= self.lowbit(i)
        return result

    def update(self, index, x):
        value = self.query(index) - self.query(index - 1)
        self.add(index, x - value)

    def add(self, index, x):
        i = index + 1
        while i < len(self.bit):
            self.bit[i] += x
            i += self.lowbit(i)

    def __str__(self):
        arr = [self.query(i) - self.query(i - 1) for i in range(len(self.bit) - 1)]
        return str(arr)

    def lowbit(self, x):
        return x & -x

class BinaryIndexedTreeMax:
    def __init__(self, n):
        self.bit = [0] * (n + 1)

    def query(self, index):
        result = 0
        i = index + 1
        while i > 0:
            result = max(result, self.bit[i])
            i -= self.lowbit(i)
        return result

    def update(self, index, x):
        i = index + 1
        while i < len(self.bit):
            self.bit[i] = max(self.bit[i], x)
            i += self.lowbit(i)

    def lowbit(self, x):
        return x & -x

class SparseTableMax:
    def __init__(self, nums):
        self.nums = nums
        n = len(nums)
        logN = (n.bit_length() - 1)
        self.st = [[0] * (logN + 1) for _ in range(n * 2)]
        for i in range(n):
            self.st[i][0] = nums[i]
        for j in range(1, logN + 1):
            for i in range(n):
                self.st[i][j] = self.st[i][j - 1]
                if i + (1 << (j - 1)) < n:
                    self.st[i][j] = max(self.st[i][j], self.st[i + (1 << (j - 1))][j - 1])

    def query(self, left, right):
        if left > right:
            return -1
        length = right - left + 1
        k = (length.bit_length() - 1)
        return max(self.st[left][k], self.st[right - (1 << k) + 1][k])

class SparseTableMin:
    def __init__(self, nums):
        self.nums = nums
        n = len(nums)
        logN = (n.bit_length() - 1)
        self.st = [[10**9] * (logN + 1) for _ in range(n * 2)]
        for i in range(n):
            self.st[i][0] = nums[i]
        for j in range(1, logN + 1):
            for i in range(n):
                self.st[i][j] = self.st[i][j - 1]
                if i + (1 << (j - 1)) < n:
                    self.st[i][j] = min(self.st[i][j], self.st[i + (1 << (j - 1))][j - 1])

    def query(self, left, right):
        if left > right:
            return -1
        length = right - left + 1
        k = (length.bit_length() - 1)
        return min(self.st[left][k], self.st[right - (1 << k) + 1][k])

class PrefixSum2D:
    def __init__(self, grid):
        self.grid = grid
        m, n = len(grid), len(grid[0])
        self.prefix = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            row = 0
            for j in range(n):
                row += grid[i][j]
                self.prefix[i + 1][j + 1] = self.prefix[i][j + 1] + row

    def query(self, up, left, bottom, right):
        return (self.prefix[up][left] + self.prefix[bottom + 1][right + 1] -
                self.prefix[bottom + 1][left] - self.prefix[up][right + 1])

