def edgesToGraph(n, edges, directed=False):
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        if not directed:
            graph[b].append(a)
    return graph

def printNums(nums):
    if not nums:
        print()
        return
    for i in range(len(nums) - 1):
        writer.write(str(nums[i]))
        writer.write(' ')
    writer.write(str(nums[-1]) + '\n')

def lengthOfLIS(numsInput):
    nums = unify(numsInput)
    bit = BinaryIndexedTreeMax(len(nums) + 1)
    result = 0
    for num in nums:
        length = bit.query(num - 1) + 1
        bit.update(num, length)
        result = max(result, length)
    return result

def unify(nums):
    sorted_nums = sorted(nums)
    numToIndex = {num: idx for idx, num in enumerate(sorted_nums)}
    return [numToIndex[num] for num in nums]

def fastPow(a, exp, mod):
    result = 1 % mod
    base = a % mod
    remain = exp
    while remain != 0:
        if remain % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        remain //= 2
    return result

def gcd(a, b):
    return math_gcd(a, b)

def gcdL(a, b):
    return math_gcd(a, b)

def lcm(a, b):
    return (a * b) // gcd(a, b)

def lcmL(a, b):
    return (a * b) // gcdL(a, b)

def wordToCharCount(word):
    charCount = [0] * 26
    for char in word:
        charCount[toIndex(char)] += 1
    return charCount

def toIndex(c):
