def toDigit(c):
    return ord(c) - ord('0')

def toYesNo(value, upper=False):
    yesNo = "Yes" if value else "No"
    return yesNo.upper() if upper else yesNo

def modSum(arr, mod=998244353):
    s = 0
    for num in arr:
        s = (s + num) % mod
    return s

def swap_int(arr, i, j):
    arr[i], arr[j] = arr[j], arr[i]

def swap_long(arr, i, j):
    arr[i], arr[j] = arr[j], arr[i]

def swap_char(arr, i, j):
    arr[i], arr[j] = arr[j], arr[i]

def toArrayDeque(lst):
