    print(requiredLen(n, x))

def requiredLen(n, x):
    MAX = 10000
    queue = toArrayDeque([x])
    step = 0
    while queue:
        next_list = []
        while queue:
            num = queue.popleft()
            if num < 0:
                return step
            s = str(num)
            if len(s) == n:
                return step
            if len(s) > n:
                continue
            digits = [False] * 10
            for ch in s:
                d = toDigit(ch)
                if d <= 1 or digits[d]:
                    continue
                digits[d] = True
                next_list.append(num * d)
        next_list.sort(reverse=True)
        for v in next_list[:min(MAX, len(next_list))]:
            queue.append(v)
        step += 1
    return -1

def requiredLen1(n, x):
    queue = toArrayDeque([x])
    step = 0
    while queue:
        nextQueue = deque()
        maxLen = 0
        while queue:
            num = queue.popleft()
            if num < 0:
                return step
            s = str(num)
            if len(s) == n:
                return step
            if len(s) > n:
                continue
            digits = [False] * 10
            for ch in s:
                digits[toDigit(ch)] = True
            for d in range(2, 10):
                if not digits[d]:
                    continue
                nextNum = num * d
                nextStr = str(nextNum)
                nextQueue.append((nextNum, nextStr))
                maxLen = max(maxLen, len(nextStr))
        for num, s in nextQueue:
            queue.append(num)
        step += 1
    return -1

