class UnionFind:
    def __init__(self):
        self.parents = {}
        self.sizes = {}

    def union(self, a, b):
        fa = self.find(a)
        fb = self.find(b)
        if fa != fb:
            self.parents[fa] = fb
            self.sizes[fb] = (self.sizes.get(fb, 1) + self.sizes.get(fa, 1))

    def find(self, a):
        def get_or_default(value):
            return self.parents.get(value, value)

        parent = get_or_default(a)
        while parent != get_or_default(parent):
            self.parents[parent] = get_or_default(get_or_default(parent))
            parent = self.parents[parent]
        return parent

    def connected(self, a, b):
        return self.find(a) == self.find(b)

    def getSize(self, a):
        return self.sizes.get(self.find(a), 1)


