class Trie:
    class Node:
        def __init__(self):
            self.hasWord = False
            self.children = {}

    def __init__(self):
        self.root = Trie.Node()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = Trie.Node()
            node = node.children[char]
        node.hasWord = True

    def search(self, word):
        node = self.findNode(word)
        return node.hasWord if node is not None else False

    def startsWith(self, prefix):
        return self.findNode(prefix) is not None

    def findNode(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return None
            node = node.children[char]
        return node


class BinaryIndexedTree:
    def __init__(self, arg):
        if isinstance(arg, int):
            self.bit = [0] * (arg + 1)
        else:
            nums = arg
            self.bit = [0] * (len(nums) + 1)
            prefix = [0] * len(self.bit)
            for i in range(1, len(nums) + 1):
                prefix[i] = prefix[i - 1] + nums[i - 1]
                self.bit[i] = prefix[i] - prefix[i - self.lowbit(i)]

    def query(self, index):
        result = 0
        i = index + 1
        while i > 0:
            result += self.bit[i]
            i -= self.lowbit(i)
        return result

    def update(self, index, x):
        value = self.query(index) - self.query(index - 1)
        self.add(index, x - value)

    def add(self, index, x):
        i = index + 1
        while i < len(self.bit):
            self.bit[i] += x
            i += self.lowbit(i)

    def __str__(self):
        arr = [self.query(i) - self.query(i - 1) for i in range(len(self.bit) - 1)]
        return str(arr)

    @staticmethod
    def lowbit(x):
        return x & -x


class BinaryIndexedTreeMax:
