    MAX = 10000
    queue = toArrayDeque([x])
    step = 0
    while queue:
        next_list = []
        while queue:
            num = queue.popleft()
            if num < 0:
                return step
            s = str(num)
            if len(s) == n:
                return step
            if len(s) > n:
