            bit[i] = prefix[i] - prefix[i - lowbit(i)]
        }
    }

    fun query(index: Int): Int {
        var result = 0
        var i = index + 1
        while (i > 0) {
            result += bit[i]
            i -= lowbit(i)
        }
        return result
