        val value = query(index) - query(index - 1)
        add(index, x - value)
    }

    fun add(index: Int, x: Int) {
        var i = index + 1
        while (i < bit.size) {
            bit[i] += x
            i += lowbit(i)
        }
    }

    override fun toString(): String {
        return IntArray(bit.size - 1) { query(it) - query(it - 1) }.toList().toString()
    }

    private fun lowbit(x: Int): Int {
