class SparseTableMax(private val nums: IntArray) {

    private val st: Array<IntArray>

    init {
        val n = nums.size
        val logN = Integer.numberOfTrailingZeros(Integer.highestOneBit(n))
        this.st = Array(n * 2) { IntArray(logN + 1) }
        for (i in 0 until n) {
            st[i][0] = nums[i]
        }
        for (j in 1 until logN + 1) {
            for (i in 0 until n) {
                st[i][j] = st[i][j - 1]
                if (i + 1.shl(j - 1) < n) {
                    st[i][j] = Math.max(st[i][j], st[i + 1.shl(j - 1)][j - 1])
                }
            }
        }
