    fun query(left: Int, right: Int): Int {
        if (left > right) {
            return -1
        }
        val len = right - left + 1
        val k = Integer.numberOfTrailingZeros(Integer.highestOneBit(len))
        return Math.max(st[left][k], st[right - 1.shl(k) + 1][k])
    }
