private fun fastPow(a: Long, exp: Long, mod: Long): Long {
    var result = 1L % mod
    var base = a % mod
    var remain = exp
    while (remain != 0L) {
        if (remain % 2L == 1L) {
            result = (result * base) % mod
        }
        base = (base * base) % mod
        remain /= 2L
    }
    return result
}

