private fun requiredLen(n: Int, x: Long): Int {
    val MAX = 10000
    val queue = listOf(x).toArrayDeque()
    var step = 0
    while (queue.isNotEmpty()) {
        val next = mutableListOf<Long>()
        while (queue.isNotEmpty()) {
            val num = queue.removeFirst()
            if (num < 0L) {
                return step
            }
            val str = num.toString()
            if (str.length == n) {
                return step
            }
            if (str.length > n) {
                continue
            }
            val digits = BooleanArray(10)
            for (char in str) {
                val d = char.toDigit()
                if (d <= 1 || digits[d]) {
                    continue
                }
                digits[d] = true
                next.add(num * d)
            }
        }
        next.sortBy { -it }
        queue.addAll(next.subList(0, Math.min(MAX, next.size)))
        step++
    }
    return -1
}

private fun requiredLen1(n: Int, x: Long): Int {
    val queue = listOf(x).toArrayDeque()
    var step = 0
    while (queue.isNotEmpty()) {
        val nextQueue = ArrayDeque<Pair<Long, String>>()
        var maxLen = 0
        while (queue.isNotEmpty()) {
            val num = queue.removeFirst()
            if (num < 0L) {
                return step
            }
            val str = num.toString()
            if (str.length == n) {
                return step
            }
            if (str.length > n) {
                continue
            }
            val digits = BooleanArray(10)
            for (char in str) {
                digits[char.toDigit()] = true
            }
            for (d in 2 until 10) {
                if (!digits[d]) {
                    continue
                }
                val nextNum = num * d
                val nextStr = nextNum.toString()
                nextQueue.addLast(Pair(nextNum, nextStr))
                maxLen = Math.max(maxLen, nextStr.length)
            }
        }
        for ((num, str) in nextQueue) {
            // if (str.length >= maxLen - 3) {
                queue.addLast(num)
            // }
        }
        step++
        // println(queue)
    }
    return -1
}

