        prefix = Array(m + 1) { IntArray(n + 1) }
        for (i in 0 until m) {
            var row = 0
            for (j in 0 until n) {
                row += grid[i][j]
                prefix[i + 1][j + 1] = prefix[i][j + 1] + row
            }
        }
    }

    fun query(up: Int, left: Int, bottom: Int, right: Int): Int {
        return prefix[up][left] + prefix[bottom + 1][right + 1] -
            prefix[bottom + 1][left] - prefix[up][right + 1]
    }
}

