typealias Graph = Array<MutableList<Int>>

private fun edgesToGraph(n: Int, edges: Array<List<Int>>, directed: Boolean = false): Graph {
    val graph = Array(n) { mutableListOf<Int>() }
    for ((a, b) in edges) {
        graph[a].add(b)
        if (!directed) {
            graph[b].add(a)
        }
    }
    return graph
}

